import { RankingDeptos } from "@/presentation-en/components/graficos/RankingDeptos";
import { SerieAnual } from "@/presentation-en/components/graficos/SerieAnual";
import { TEXTOS, type Modo } from "@/presentation-en/lib/focos/modo";
import type { Resumen } from "@/lib/focos/tipos";
