import estilos from "@/components/sitio/Estacionalidad.module.css";

function titular(t: Resumen["aqua"]["tendencia"], modo: Modo): string {
  const T = TEXTOS[modo];
  const incendios = modo === "incendios";
  const porDecada = Math.abs(t.senAnual * 10);
  if (t.senAnual === 0) return `Between ${t.desde} and ${t.hasta}, ${T.sujetoSerie} shows no net change.`;
  const baja = t.senAnual < 0;
  const verbo = incendios
    ? t.significativa
      ? baja
        ? "decreased"
        : "increased"
      : baja
        ? "tended to decrease"
        : "tended to increase"
    : t.significativa
      ? baja
        ? "decreased"
        : "increased"
      : baja
        ? "tended to decrease"
        : "tended to increase";
  return `Between ${t.desde} and ${t.hasta}, ${T.sujetoSerie} ${verbo} by about ${decimal(porDecada, 0)} ${T.unidadSerie} per decade.`;
}

export function Estacionalidad({ resumen, modo = "focos" }: { resumen: Resumen; modo?: Modo }) {
  const T = TEXTOS[modo];
  const incendios = modo === "incendios";
  const { aqua, todos } = resumen;
  const t = aqua.tendencia;
  const t2 = aqua.tendenciaSinFaltantes;
  const conFaltantes = aqua.anual.filter((d) => d.mesesSinDato > 0).length;
  const aquaSat = todos.porSatelite.find((s) => s.satelite === "AQUA");

  return (
    <section id="estacionalidad" className="seccion seccion-alterna" aria-labelledby="titulo-estacionalidad">
      <div className="contenedor">
        <div className="seccion-cabeza">
          <h2 id="titulo-estacionalidad"> Historical record analysis </h2>
          <p>
            {incendios
              ? "We use a single product, MCD64A1 (monthly MODIS burned area), from November 2000 onward. This avoids changes in the active satellite mix and allows comparisons across complete years."
              : "To compare years, we use a single satellite, Aqua, which observed San Luis with the same sensor throughout the record. Adding new satellites could create an apparent increase simply because more sensors are observing."}
          </p>
        </div>

        <div className={estilos.tendencia} id="tendencia">
          <div className={estilos.tendenciaTexto}>
            <h3 className={estilos.tendenciaTitulo}>Trend from {t.desde} to {t.hasta}</h3>
            <p className={estilos.titular}>{titular(t, modo)}</p>
            <p className={estilos.insignia} data-significativa={t.significativa}>
              <svg width="18" height="18" viewBox="0 0 18 18" aria-hidden="true">
                {t.significativa ? (
                  <path d="M3.5 9.5l3.5 3.5 7.5-8" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" />
                ) : (
                  <path d="M3 10c2-3 4-3 6 0s4 3 6 0" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" />
                )}
              </svg>
              {t.significativa ? "Significant" : "Inconclusive"}
            </p>
            <p className={estilos.explica}>
              {t.significativa
                ? `The Mann–Kendall test gives ${valorP(t.p)}: a change this large is unlikely to occur by chance if there were no underlying trend.`
                : `The Mann–Kendall test gives ${valorP(t.p)}. With such large differences between years, a change of this size can occur by chance without a real trend. More years or a stronger signal are needed to establish one.`}
            </p>
            <dl className={estilos.datos}>
              <div>
                <dt>Change per decade</dt>
                <dd>
                  {t.senAnual < 0 ? "−" : "+"}
                  {decimal(Math.abs(t.senAnual * 10), 0)} {T.unidadSerie}
                </dd>
              </div>
              <div>
                <dt>P-value</dt>
                <dd>{decimal(t.p, 3)}</dd>
              </div>
              <div>
                <dt>Years analyzed</dt>
                <dd>{t.n}</dd>
              </div>
            </dl>
            <p className="nota"> Change per decade based on Sen’s slope, which is less sensitive to an extreme year. {conFaltantes} of the{" "}
              {t.n} years have at least one month with missing data; excluding them gives {valorP(t2.p)}
              {t2.significativa === t.significativa ? " and the conclusion is unchanged." : " and the conclusion changes: interpret it cautiously."}
            </p>

            <p className={`nota ${estilos.pieNota}`}>
              {incendios
                ? `Record from ${aqua.desde.replace("-", "/")} to ${aqua.hasta.replace("-", "/")}: ${entero(aqua.total)} burned hectares according to MCD64A1, alongside ${entero(todos.total)} fire-associated detections. Only complete years are analyzed.`
                : `Record from ${aqua.desde.replace("-", "/")} to ${aqua.hasta.replace("-", "/")}: ${entero(aqua.total)} hotspots from Aqua${aquaSat ? ` out of ${entero(todos.total)} detected by all satellites` : ""}. Only complete years are analyzed.`}
            </p>
          </div>
          <figure className={estilos.tendenciaGrafico}>
            <figcaption className={estilos.leyendaSerie}>
              <span>
                <svg width="22" height="12" aria-hidden="true">
                  <line x1="0" y1="6" x2="22" y2="6" stroke="#b8c0c8" strokeWidth="2" />
                  <circle cx="11" cy="6" r="4" fill="#ece8df" />
                </svg>
                {T.eje}
              </span>
              <span>
                <svg width="14" height="14" aria-hidden="true">
                  <circle cx="7" cy="7" r="4.5" fill="#13202d" stroke="#ece8df" strokeWidth="2" />
                </svg> year with missing months </span>
              <span>
                <svg width="26" height="12" aria-hidden="true">
                  <line x1="0" y1="6" x2="26" y2="6" stroke="#f8b44e" strokeWidth="2.5" strokeDasharray="7 5" />
                </svg> trend (Sen’s slope) </span>
            </figcaption>
            <SerieAnual
              anual={aqua.anual}
              tendencia={t}
              t={T}
            />
          </figure>

        </div>


        <div className={estilos.dos}>
          <BarrasMes estacionalidad={aqua.estacionalidad} mesPico={aqua.mesPico} desde={aqua.desde} hasta={aqua.hasta} t={T} />
          <RankingDeptos ranking={aqua.ranking} t={T} />
        </div>

        <div className={estilos.matriz}>
          <MatrizAnioMes matriz={aqua.matriz} t={T} modo={modo} />
        </div>
      </div>
    </section>
  );
}
